"""Read-only one male jaw + existing mouth-width operator reuse audit."""
from pathlib import Path
import sys,json,gzip,hashlib
import numpy as np
ROOT=Path(__file__).resolve().parents[2];OUT=Path(__file__).resolve().parent
sys.path.insert(0,str(ROOT/'scripts/m2-male-face-v1'))
from glb import GLB
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
J=ROOT/'assets-source/m2-male-face-v1';M=ROOT/'assets-source/face-parameters-v1';s=json.loads((J/'spec.json').read_text());b=json.loads((J/'generated/build-report.json').read_text());parent=ROOT/s['sourceVRM'];jaw=J/'generated/avatar.vrm';blend=J/'generated/editable.blend';assert sha(parent)==s['sourceVRMSha256'];assert sha(jaw)==b['avatarSha256'];assert sha(blend)==b['editableBlendSha256'];g=GLB(parent);j=GLB(jaw);m=g.doc['meshes'][1];jm=j.doc['meshes'][1];p=m['primitives'][0];jp=jm['primitives'][0];x=g.acc(p['attributes']['POSITION']);y=j.acc(jp['attributes']['POSITION']);delta=y.astype(float)-x;changed=np.flatnonzero(np.linalg.norm(delta,axis=1)>1e-8)
recipepath=M/'male-mouth-width.recipe.json';recipe=json.loads(recipepath.read_text());assert recipe['baseAvatarSha256']==sha(parent);weights=np.array(recipe['weights']);mouth=np.flatnonzero(weights>0);tri=np.concatenate([g.acc(pr['indices']).reshape(-1,3)for pr in m['primitives']]);hood=lambda ids:np.unique(tri[np.any(np.isin(tri,ids),axis=1)]);jn=hood(changed);mn=hood(mouth);shared=np.intersect1d(changed,mouth);normalShared=np.intersect1d(jn,mn)
sourcepath=J/'generated/source-delta.json.gz';mappingpath=M/'generated/male-mouth-width-104-v1/mapping.json.gz';src=json.loads(gzip.decompress(sourcepath.read_bytes()));mp=json.loads(gzip.decompress(mappingpath.read_bytes()));sx=np.array(src['sourcePositions']);mx=np.array(mp['sourcePositions']);assert np.array_equal(sx,mx);sd=np.array(src['delta']);sw=np.array(mp['sourceVertexWeights']);sourceShared=np.flatnonzero((np.linalg.norm(sd,axis=1)>1e-12)&(sw>0));attrs=[]
for om,nm in zip(g.doc['meshes'],j.doc['meshes']):
 for a,c in zip(om['primitives'],nm['primitives']):
  attrs.append({'material':g.doc['materials'][a['material']]['name'],'indicesEqual':bool(np.array_equal(g.acc(a['indices']),j.acc(c['indices']))),'attributesEqual':{k:bool(np.array_equal(g.acc(v),j.acc(c['attributes'][k])))for k,v in a['attributes'].items()}})
