 u=g.acc(a['POSITION']);v=j.acc(c['POSITION']);shapes.append({'name':name,'relativeDeltaMaxErrorM':float(np.linalg.norm(u.astype(float)-v,axis=1).max()),'mouthRelativeDeltaMaxErrorM':float(np.linalg.norm(u[mouth].astype(float)-v[mouth],axis=1).max())})
